self.addEventListener("push",i=>{if(i.data)try{let t=i.data.json(),n=t.title??"Reckoning",o={body:t.body??"You have a new notification.",icon:t.icon??"/android-chrome-192x192.png",badge:t.badge??"/android-chrome-192x192.png",tag:t.tag??"reckoning-notification",vibrate:[200,100,200],data:{url:t.url??"/dashboard/my-reports",...t.data},actions:[{action:"open",title:"View"},{action:"dismiss",title:"Dismiss"}]};i.waitUntil(self.registration.showNotification(n,o))}catch{let t=i.data?.text()??"You have a new notification.";i.waitUntil(self.registration.showNotification("Reckoning",{body:t}))}}),self.addEventListener("notificationclick",i=>{if(i.notification.close(),"dismiss"===i.action)return;let t=i.notification.data?.url??"/dashboard/my-reports";i.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(i=>{for(let n of i)if(n.url.includes(t)&&"focus"in n)return n.focus();return self.clients.openWindow(t)}))});